import os, subprocess, sys, tempfile, unittest

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from tabula import engine

PEOPLE = "id,city,n\n1,Leeds,a\n2,York,b\n3,Leeds,c\n4,York,d\n5,Hull,e\n"


def run_cli(*argv, files=None):
    with tempfile.TemporaryDirectory() as d:
        for k, v in (files or {}).items():
            with open(os.path.join(d, k), "w", encoding="utf-8", newline="") as fh:
                fh.write(v)
        env = dict(os.environ, PYTHONPATH=os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
        p = subprocess.run([sys.executable, "-m", "tabula"] + list(argv), cwd=d, env=env, capture_output=True, text=True)
        return p.returncode, p.stdout, p.stderr


def dedupe_csv(text, *args):
    return run_cli("--format=csv", "dedupe", "t.csv", *args, files={"t.csv": text})


class DedupeResultTests(unittest.TestCase):
    def test_results(self):
        cases = [
            (PEOPLE, ("city",), (), "id,city,n\n1,Leeds,a\n2,York,b\n5,Hull,e\n"),
            (PEOPLE, ("city",), ("--keep", "first"), "id,city,n\n1,Leeds,a\n2,York,b\n5,Hull,e\n"),
            # survivors stay in file order, not in order of first appearance of their key
            (PEOPLE, ("city",), ("--keep", "last"), "id,city,n\n3,Leeds,c\n4,York,d\n5,Hull,e\n"),
            (PEOPLE, ("city",), ("--keep=last",), "id,city,n\n3,Leeds,c\n4,York,d\n5,Hull,e\n"),
            ("k,v\na,1\nb,2\na,3\nb,4\nb,5\n", ("k",), ("--keep=last",), "k,v\na,3\nb,5\n"),
            # all KEY columns must match
            ("a,b,c\n1,x,p\n1,y,q\n1,x,r\n2,x,s\n", ("a", "b"), (), "a,b,c\n1,x,p\n1,y,q\n2,x,s\n"),
            ("a,b,c\n1,x,p\n1,y,q\n1,x,r\n2,x,s\n", ("b", "a"), ("--keep", "last"), "a,b,c\n1,y,q\n1,x,r\n2,x,s\n"),
            # a column named twice is the same as once
            ("a,b\n1,x\n1,y\n", ("a", "a"), (), "a,b\n1,x\n"),
            # text equality only; empty cells equal each other
            ("a\n1\n1.0\n 1\nx\nX\n\"\"\n\"\"\n", ("a",), (), "a\n1\n1.0\n 1\nx\nX\n\"\"\n"),
            ("a,b\n,1\n,2\n", ("a",), ("--keep=last",), "a,b\n,2\n"),
            ("a,b\n1,x\n", ("a",), (), "a,b\n1,x\n"),
            ("a,b\n", ("a",), (), "a,b\n"),
        ]
        for text, keys, opts, want in cases:
            with self.subTest(text=text[:30], keys=keys, opts=opts):
                self.assertEqual(dedupe_csv(text, *keys, *opts), (0, want, ""))

    def test_formats_and_option_places(self):
        f = {"t.csv": PEOPLE}
        self.assertEqual(run_cli("dedupe", "t.csv", "city", files=f),
                         (0, "id  city   n\n1   Leeds  a\n2   York   b\n5   Hull   e\n", ""))
        self.assertEqual(run_cli("--format", "json", "dedupe", "--keep", "last", "t.csv", "city", files=f),
                         (0, '[{"id": "3", "city": "Leeds", "n": "c"}, {"id": "4", "city": "York", "n": "d"}, '
                             '{"id": "5", "city": "Hull", "n": "e"}]\n', ""))
        self.assertEqual(run_cli("--keep=last", "dedupe", "t.csv", "city", "--format=csv", files=f),
                         (0, "id,city,n\n3,Leeds,c\n4,York,d\n5,Hull,e\n", ""))

    def test_keep_not_read_by_other_commands(self):
        self.assertEqual(run_cli("--keep", "last", "show", "t.csv", files={"t.csv": PEOPLE})[1],
                         run_cli("show", "t.csv", files={"t.csv": PEOPLE})[1])
